use vlajmaji::lexicon::*;
use vlajmaji::search::{DictionarySearchEngine, DictionaryExactOptions,DictionaryQueryError,ReferenceStatus};
use sha2::{Digest,Sha256};
use std::collections::{BTreeMap,BTreeSet};
fn sha(x:&[u8])->String{format!("{:x}",Sha256::digest(x))}
fn options(raw:&[u8])->SutysiskuImportOptions{SutysiskuImportOptions{revision:"0".repeat(40),expected_raw_sha256:sha(raw),raw_locator:Some("https://example.invalid/synthetic-sut".into()),notice_locator:Some("https://example.invalid/synthetic-software-notice".into())}}
fn sut(raw:&[u8])->SutysiskuImport{import_sutysisku_export(raw,&options(raw)).unwrap()}
const FIXTURE:&[u8]=include_bytes!("../../public-fixture.json");
const CENSUS:&[u8]=include_bytes!("../../public-fixture-census01.json");
const LENSISKU:&[u8]=br#"[{"word":"farvi","word_type":"gismu","definition":"synthetic develops","definition_id":333,"score":1.2500,"user":{"username":"shared"}}]"#;
fn la()->Dictionary{import_la_lojban_export(LENSISKU,&LaLojbanImportOptions{revision:"0".repeat(40),expected_raw_sha256:sha(LENSISKU),raw_locator:Some("https://example.invalid/synthetic-la".into()),notice_locator:Some("https://example.invalid/software".into())}).unwrap().into_dictionary()}
fn jb()->Dictionary{let m=format!("language_tag = \"en\"\nlanguage_realname = \"English\"\nsource_language_tag = \"jbo\"\nformat = \"json\"\npositive_scores_only = false\nfilename = \"dictionary-en.json\"\nmetadata_url = \"https://example.invalid/languages\"\ndownload_url = \"https://example.invalid/synthetic\"\nlensisku_created_at = \"2026-10-04T03:07:08Z\"\nsha256 = \"{}\"\ndefinition_count = 1\nentry_count = 1\n",sha(LENSISKU));import_jbotci_export(LENSISKU,m.as_bytes(),&JbotciImportOptions{revision:"0".repeat(40),expected_raw_sha256:sha(LENSISKU),expected_metadata_sha256:sha(m.as_bytes())}).unwrap().into_dictionary()}
fn llg()->Dictionary{let mut g=vec![b' ';158];g[1..6].copy_from_slice(b"farvi");g[62..63].copy_from_slice(b"d");let n=b"Explicit synthetic notice";import_llg_lists(&g,b"",b"",n,&LlgImportOptions{expected_gismu_sha256:sha(&g),expected_cmavo_sha256:sha(b""),expected_rafsi_sha256:sha(b""),expected_notice_sha256:sha(n),base_locator:"https://example.invalid/synthetic-llg".into()}).unwrap().into_dictionary()}
fn rows<T:serde::Serialize>(v:&[T])->BTreeMap<String,usize>{let mut out=BTreeMap::new();for x in v{*out.entry(sha(&serde_json::to_vec(x).unwrap())).or_insert(0)+=1;}out}
fn inventory(d:&Dictionary)->BTreeMap<&'static str,BTreeMap<String,usize>>{
 let mut out=BTreeMap::new();let m=d.metadata();let r=d.registry().as_document();
 macro_rules! add{($($name:ident),*)=>{$(out.insert(stringify!($name),rows(&m.$name));)*}}
 add!(collections,components,releases,code_notices,entries,assertions,contexts,forms,etymologies,frames,relations,owned_revisions,owned_heads,editorial_senses,computations,annotations,extensions);
 out.insert("sources",rows(&r.sources));out.insert("contributors",rows(&r.contributors));out.insert("distributors",rows(&r.distributors));out.insert("aliases",rows(&r.aliases));out.insert("lineage",rows(&r.lineage));out.insert("snapshots",rows(&r.snapshots));out.insert("occurrences",rows(&r.occurrences));out.insert("captures",rows(d.captures()));out
}
fn main(){
 let census:serde_json::Value=serde_json::from_slice(CENSUS).unwrap();assert_eq!(census["fixture_sha256"],sha(FIXTURE));
 let input=sut(FIXTURE);let report=input.report();let d=input.dictionary();let m=d.metadata();
 assert_eq!((report.input_rows,report.native_child_fields,report.native_fields,report.lexical_occurrences,report.excluded_occurrences),(6,22,29,2,4));
 assert_eq!((m.contexts.len(),m.forms.len(),m.extensions.len()),(3,2,8));
 assert_eq!(d.captures()[0].bytes,FIXTURE);assert_eq!(d.captures()[0].occurrences[0].fields[0].raw_value,r#""\u0066arvi""#);assert_eq!(d.captures()[0].occurrences[1].fields[0].raw_value,r#""farvi""#);
 assert_eq!(m.entries[0].spelling,Presence::Value("farvi".into()));assert_eq!(m.entries[1].spelling,m.entries[0].spelling);assert_ne!(m.assertions[0].occurrence,m.assertions[1].occurrence);
 assert_eq!(report.diagnostics.get("duplicate_root_key"),Some(&2));
 for i in [0,1]{assert!(m.releases[0].diagnostics.iter().any(|x|x.code=="duplicate_root_key" && x.occurrence.as_ref().is_some_and(|o|o.locator==format!("/{i}"))));}
 assert!(m.releases[0].diagnostics.iter().any(|x|x.message.contains("/5/u~1a~0/x~1y~0")));
 assert_eq!(d.captures()[0].occurrences[3].fields[1].name,"$row");assert_eq!(d.captures()[0].occurrences[3].fields[1].raw_value,"42");
 for x in &m.extensions{let ev=x.evidence.as_ref().unwrap();let occ=d.occurrence(&ev.occurrence).unwrap();assert_eq!(occ.fields[ev.field_index.unwrap() as usize].raw_value,x.value.as_str());}
 assert_eq!(m.forms.iter().map(|x|x.spelling.as_str()).collect::<Vec<_>>(),vec!["fav","farv"]);assert!(m.forms.iter().all(|x|x.kind==FormKind::SourceReportedForm));
 for (field,value,code) in [("s","{}","invalid_selmaho"),("n","[]","invalid_notes"),("g","[\"valid\",3]","invalid_glosses"),("r","[\"fav\",3]","invalid_reported_form")] {
  let raw=format!("{{\"farvi\":{{\"d\":\"d\",\"t\":\"gismu\",\"{field}\":{value}}}}}");let x=sut(raw.as_bytes());assert_eq!(x.report().lexical_occurrences,1,"{field}");assert!(x.report().diagnostics.contains_key(code),"{field}");assert_eq!(x.dictionary().captures()[0].occurrences[0].fields.last().unwrap().raw_value,value);
  if field=="g"{assert!(x.dictionary().metadata().contexts.is_empty());assert_eq!(x.dictionary().metadata().extensions[0].value.as_str(),value);}
  if field=="r"{assert!(x.dictionary().metadata().forms.is_empty());}
 }
 for field in ["s","n","g","r","b"]{let raw=format!("{{\"farvi\":{{\"d\":\"d\",\"t\":\"gismu\",\"{field}\":null}}}}");let x=sut(raw.as_bytes());assert_eq!(x.report().lexical_occurrences,1);assert_eq!(x.dictionary().captures()[0].occurrences[0].fields.last().unwrap().raw_value,"null");}
 let form_raw=include_bytes!("../../form-fixture.json");let boundary=sut(form_raw);let bm=boundary.dictionary().metadata();assert_eq!(boundary.report().native_fields,8);assert_eq!(bm.forms.iter().map(|f|f.spelling.as_str()).collect::<Vec<_>>(),vec!["f","farvi","farvi","","λ"]);assert_eq!(bm.contexts.len(),1);assert_eq!(bm.contexts[0].kind,ContextKind::Note);assert_eq!(bm.contexts[0].value,Presence::Null);assert_eq!(bm.extensions.len(),2);assert!(!boundary.report().diagnostics.contains_key("invalid_reported_form"));
 let empty=sut(br#"{"":{"d":"d","t":"gismu"}}"#);assert_eq!(empty.report().excluded_occurrences,1);assert_eq!(empty.dictionary().registry().as_document().occurrences[0].native_entry_id.as_deref(),Some(""));
 let unknown=sut(br#"{"farvi":{"d":"d","t":"invented"}}"#);assert_eq!(unknown.report().excluded_occurrences,1);assert_eq!(unknown.dictionary().metadata().entries[0].native_word_class,Presence::Value("invented".into()));
 for raw in [b"[1]".as_slice(),b"{",b"null"]{assert!(matches!(import_sutysisku_export(raw,&options(raw)),Err(SutysiskuImportError::InvalidJson(_))));}
 let raw=b"\xff";assert!(matches!(import_sutysisku_export(raw,&options(raw)),Err(SutysiskuImportError::InvalidUtf8)));
 let mut bad=options(FIXTURE);bad.expected_raw_sha256="0".repeat(64);assert!(matches!(import_sutysisku_export(FIXTURE,&bad),Err(SutysiskuImportError::HashMismatch{..})));bad=options(FIXTURE);bad.revision="bad".into();assert!(matches!(import_sutysisku_export(FIXTURE,&bad),Err(SutysiskuImportError::InvalidOptions(_))));
 let same=compose_dictionaries(vec![sut(FIXTURE).into_dictionary(),sut(FIXTURE).into_dictionary()]).unwrap();assert_eq!(&same,input.dictionary(),"byte-identical repeated received pack is idempotent, not new attestation");
 let mut o=SutysiskuImportOptions::default();o.expected_raw_sha256=sha(FIXTURE);o.revision="1".repeat(40);let other=import_sutysisku_export(FIXTURE,&o).unwrap();assert!(other.dictionary().captures()[0].metadata.locator.contains(&format!("/{}/data/parsed-en.json",o.revision)));assert_ne!(other.dictionary().metadata().releases[0].id,m.releases[0].id);assert_eq!(other.dictionary().metadata().assertions[0].occurrence,m.assertions[0].occurrence);assert!(matches!(compose_dictionaries(vec![input.clone().into_dictionary(),other.into_dictionary()]),Err(PackError::Conflict{..})));
 for kind in ["source","distributor"]{let mut doc=sut(FIXTURE).into_dictionary().into_document();let mut reg=doc.registry.into_document();if kind=="source"{reg.sources[0].display_name="conflicting body".into();}else{reg.distributors[0].display_name="conflicting body".into();}doc.registry=SourceRegistry::from_document(reg).unwrap();let changed=Dictionary::from_document(doc).unwrap();assert!(matches!(compose_dictionaries(vec![sut(FIXTURE).into_dictionary(),changed]),Err(PackError::Conflict{..})));}
 let excluded=input.dictionary().metadata().assertions[2].occurrence.clone();let rel=input.dictionary().metadata().releases[0].id.clone();
 let composed=compose_dictionaries(vec![input.into_dictionary(),la(),jb(),llg()]).unwrap();assert_eq!((composed.registry().as_document().sources.len(),composed.registry().as_document().distributors.len()),(3,2));
 let store=std::path::Path::new("/tmp/vlajmaji-p01-a03-cdc/s04/tiny-four-pack-store01");let engine=DictionarySearchEngine::build(store,&composed.to_json_bytes().unwrap()).unwrap();drop(engine);let s=vlajmaji::store::DictionaryStore::open(store).unwrap();assert_eq!(s.dictionary().unwrap(),composed);drop(s);let verified=vlajmaji::store::DictionaryStoreVerification::verify(store,vlajmaji::store::DictionaryStoreVerificationCheck::All).unwrap();assert!(verified.ok);let engine=DictionarySearchEngine::open(store).unwrap();
 let all=engine.exact("farvi",DictionaryExactOptions::default()).unwrap();assert_eq!((all.totals.occurrences,all.totals.source_groups,all.totals.distinct_spellings),(5,3,1));
 for (selector,n) in [("SUT",2),("LSK",2),("LLG",1)]{assert_eq!(engine.exact("farvi",DictionaryExactOptions{sources:vec![selector.into()],..Default::default()}).unwrap().totals.occurrences,n);}
 let mut got=Vec::new();let mut cursor=None;for _ in 0..5{let p=engine.exact("farvi",DictionaryExactOptions{page_size:Some(1),cursor,..Default::default()}).unwrap();assert_eq!(p.totals,all.totals);got.extend(p.groups.iter().flat_map(|g|g.hits.iter().map(|h|h.assertion.id.clone())));cursor=p.next_cursor;}assert!(cursor.is_none());assert_eq!(got,all.groups.iter().flat_map(|g|g.hits.iter().map(|h|h.assertion.id.clone())).collect::<Vec<_>>());
 assert_eq!(engine.resolve(&RelationTarget::Local(LocalRef::Assertion(got[0].clone()))).unwrap().status,ReferenceStatus::Resolved);assert_eq!(engine.resolve(&RelationTarget::Unknown).unwrap().status,ReferenceStatus::Unknown);assert_eq!(engine.exact("zoizoizoi",DictionaryExactOptions{sources:vec!["SUT".into()],..Default::default()}).unwrap().totals.occurrences,0);
 assert!(matches!(engine.resolve(&RelationTarget::Local(LocalRef::Entry(got[0].clone()))),Err(DictionaryQueryError::InvalidReference{..})));assert!(matches!(engine.resolve(&RelationTarget::Local(LocalRef::Entry(EntityId::new("cdc-missing-entry").unwrap()))),Err(DictionaryQueryError::InvalidReference{..})));
 let r=engine.resolve(&RelationTarget::Catalog(CatalogTarget{source:SourceId::new("sutysisku").unwrap(),release:rel,native_entry_id:None,native_assertion_id:None,occurrence:Some(excluded)})).unwrap();assert_eq!(r.status,ReferenceStatus::Resolved);assert_eq!(r.confirmed.len(),1);assert!(!r.confirmed[0].current_eligible && r.confirmed[0].payload_present && r.confirmed[0].raw.is_some());
 println!("PASS independent raw-key/duplicate/optional/provenance controls and tiny four-source store/pages/references");
 let bytes=vlajmaji_data_sutysisku::release_bytes();assert_eq!(bytes,vlajmaji::data_sutysisku::release_bytes());assert_eq!(vlajmaji_data_sutysisku::seal_bytes(),vlajmaji::data_sutysisku::seal_bytes());
 let models=vec![vlajmaji::data_lensisku_jbotci::load().unwrap(),vlajmaji::data_llg::load().unwrap(),vlajmaji::data_la_lojban::load().unwrap(),vlajmaji_data_sutysisku::load().unwrap()];let mut expected:BTreeMap<&'static str,BTreeMap<String,usize>>=BTreeMap::new();
 for d in &models{for (kind,rs) in inventory(d){for (hash,count) in rs{let current=expected.entry(kind).or_default().entry(hash).or_insert(0);*current=(*current).max(count);}}}
 let joined=compose_dictionaries(models).unwrap();assert_eq!(inventory(&joined),expected,"complete record/capture/registry ordered-multiplicity inventories");let m=joined.metadata();let r=joined.registry().as_document();assert_eq!((m.assertions.len(),m.entries.len(),m.contexts.len(),m.forms.len(),m.etymologies.len(),m.extensions.len()),(78361,76722,177210,11598,3513,138107));assert_eq!((r.sources.len(),r.distributors.len(),r.contributors.len(),joined.captures().len(),m.collections.len(),m.components.len(),m.releases.len()),(3,2,238,8,4,6,6));
 let entries:BTreeMap<_,_>=m.entries.iter().map(|e|(&e.id,e)).collect();let lexical:Vec<_>=m.assertions.iter().filter(|a|a.eligibility==Eligibility::Lexical).collect();assert_eq!(lexical.len(),76803);let words:BTreeSet<_>=lexical.iter().map(|a|match &entries[&a.entry].spelling{Presence::Value(x)=>x.as_str(),_=>panic!("missing eligible spelling")}).collect();assert_eq!(words.len(),31375);assert_eq!(joined.captures().iter().flat_map(|c|&c.occurrences).map(|o|o.fields.len()).sum::<usize>(),566367);
 println!("{}",serde_json::json!({"status":"PASS","full_sut_bytes":bytes.len(),"full_sut_sha256":sha(bytes),"four_pack_assertions":m.assertions.len(),"four_pack_eligible":lexical.len(),"four_pack_eligible_spellings":words.len(),"all_record_inventory_equal":true,"source_groups":r.sources.len(),"native_fields_with_sut_keys":566367}));
}
